// The profile's timeline: a paginated connection of stories, rendered with
// the same story component as the home feed. More posts load when the
// sentinel at the end comes near the viewport.
import { useCallback, useEffect, useRef } from "react";
import { graphql, usePaginationFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import FeedStory from "FeedStory.react";
import FeedGlimmer from "FeedGlimmer.react";
import LoggingSurface from "LoggingSurface.react";
import { emitStepEvent } from "Workload";
import { PROFILE_TIMELINE_PAGE_SIZE } from "ProfileTimelineConfig";

const PREFETCH_DISTANCE = 600;

const styles = stylex.create({
  sentinel: { height: 1 },
});

export default function ProfileTimeline({ user }) {
  const { data, loadNext, hasNext, isLoadingNext } = usePaginationFragment(
    graphql`
      fragment ProfileTimeline_user on User
      @refetchable(queryName: "ProfileTimelinePaginationQuery")
      @argumentDefinitions(count: { type: "Int", defaultValue: 3 }, cursor: { type: "String" }) {
        timeline_feed_units(first: $count, after: $cursor) @connection(key: "ProfileTimeline_timeline_feed_units") {
          edges {
            cursor
            node {
              __typename
              id
              ...FeedStory_story @alias(as: "story")
            }
          }
        }
      }
    `,
    user,
  );
  const sentinel = useRef(null);
  const state = useRef(null);
  state.current = { hasNext, isLoadingNext, loadNext };
  const maybeLoadNext = useCallback(() => {
    const { hasNext: more, isLoadingNext: loading, loadNext: next } = state.current;
    const near = sentinel.current !== null && sentinel.current.getBoundingClientRect().top <= window.innerHeight + PREFETCH_DISTANCE;
    if (near && more && !loading) {
      next(PROFILE_TIMELINE_PAGE_SIZE, { onComplete: () => emitStepEvent("profile-timeline-page-loaded") });
    }
  }, []);
  useEffect(() => {
    const observer = new IntersectionObserver(() => maybeLoadNext(), { rootMargin: `0px 0px ${PREFETCH_DISTANCE}px 0px` });
    observer.observe(sentinel.current);
    return () => observer.disconnect();
  }, [maybeLoadNext]);
  const edges = data.timeline_feed_units?.edges ?? [];
  return (
    <LoggingSurface name="profile_timeline" as="div">
      <div role="feed" aria-busy={isLoadingNext} data-testid="profile-timeline">
        {edges.map((edge, i) => (edge?.node?.story ? <FeedStory key={edge.node.id} story={edge.node.story} position={i} /> : null))}
      </div>
      {isLoadingNext ? <FeedGlimmer /> : null}
      <div ref={sentinel} {...stylex.props(styles.sentinel)} />
    </LoggingSurface>
  );
}
