function FriendsSection({ queryRef }) {
  const data = usePreloadedQuery(
    graphql`
      query ProfilePageFriendsQuery($vanity: String!) @preloadable {
        actor_by_vanity(vanity: $vanity) {
          ... on User {
            ...ProfileFriendsCard_user @alias(as: "user")
          }
        }
      }
    `,
    queryRef,
  );
  return data.actor_by_vanity?.user ? <ProfileFriendsCard user={data.actor_by_vanity.user} /> : null;
}

function ComposerSection({ queryRef }) {
  const data = usePreloadedQuery(
    graphql`
      query ProfilePageComposerQuery($vanity: String!) @preloadable {
        actor_by_vanity(vanity: $vanity) {
          ... on User {
            ...ProfileComposer_user @alias(as: "user")
          }
        }
      }
    `,
    queryRef,
  );
  return data.actor_by_vanity?.user ? <ProfileComposer user={data.actor_by_vanity.user} /> : null;
}

function TimelineSection({ queryRef, onRendered }) {
  const data = usePreloadedQuery(
    graphql`
      query ProfilePageTimelineQuery($vanity: String!, $count: Int!) @preloadable {
        actor_by_vanity(vanity: $vanity) {
          ... on User {
            ...ProfileTimeline_user @arguments(count: $count) @alias(as: "user")
          }
        }
      }
    `,
    queryRef,
  );
  useEffect(() => {
    onRendered("timeline");
  }, [onRendered]);
  return data.actor_by_vanity?.user ? <ProfileTimeline user={data.actor_by_vanity.user} /> : null;
}

export default function ProfilePage({ queries }) {
  const rendered = useRef(new Set());
  const onRendered = useCallback((section) => {
    rendered.current.add(section);
    if (rendered.current.size === 2) {
      emitStepEvent("profile-rendered");
    }
  }, []);
  return (
    <LoggingSurface name="profile">
      <div {...stylex.props(styles.page)}>
        <div role="banner" aria-label="Profile">
          <UIErrorBoundary name="profile_header">
            <Suspense fallback={null}>
              <HeaderSection queryRef={queries.header} onRendered={onRendered} />
            </Suspense>
          </UIErrorBoundary>
        </div>
        <div {...stylex.props(styles.body)}>
          <div role="complementary" aria-label="Profile details" {...stylex.props(styles.left)}>
            <UIErrorBoundary name="profile_intro">
              <Suspense fallback={null}>
                <IntroSection queryRef={queries.intro} />
              </Suspense>
            </UIErrorBoundary>
            <UIErrorBoundary name="profile_photos">
              <Suspense fallback={null}>
                <PhotosSection queryRef={queries.photos} />
              </Suspense>
            </UIErrorBoundary>
            <UIErrorBoundary name="profile_friends">
              <Suspense fallback={null}>
                <FriendsSection queryRef={queries.friends} />
              </Suspense>
            </UIErrorBoundary>
          </div>
          <div role="main" {...stylex.props(styles.right)}>
            <UIErrorBoundary name="profile_composer">
              <Suspense fallback={null}>
                <ComposerSection queryRef={queries.composer} />
              </Suspense>
            </UIErrorBoundary>
            <ProfileTimelineFilterBar />
            <UIErrorBoundary name="profile_timeline">
              <Suspense fallback={<FeedGlimmer />}>
                <TimelineSection queryRef={queries.timeline} onRendered={onRendered} />
              </Suspense>
            </UIErrorBoundary>
          </div>
        </div>
      </div>
    </LoggingSurface>
  );
}
